"""Keep consulted sources, exclusions and editorial boundaries alongside the new kit records."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'docs/exercise-reference'
urls=[('KT01','Thera-Band / The Hygenic Corporation','Instruction Manual 2012','https://www.tumbltrak.com/content/pdf/Assembly_Instructions/TheraBand_User_Guide.pdf','bandes et tubes, accessoires, levées/poussées, adduction, tirages, dead lift','Texte original consulté. Pas notice Decathlon ; certaines variantes diffèrent. Capture PDF non utilisée comme revue humaine.'),('KT02','ProsourceFit','Resistance Tubes Instruction Manual & Exercise Guide','https://images-na.ssl-images-amazon.com/images/I/B1p8Nh6A1ZS.pdf','squat p.6, row p.9, press p.10, fly p.11, élévations p.12, épaules p.13, pushdown p.15','Texte original consulté. Deux poignées et tubes décrits ; ancrage press souvent plus haut que variante Tempo. Notice d’une autre marque.'),('KT03','ProsourceFit','Holly Pinkham, Upper Body Resistance Band Workout','https://www.prosourcefit.com/blogs/news/resistance-band-travel-workout','poussées, écartés, overhead press, triceps, ancrage','Même groupe éditorial que KT02, ne pas compter comme nouvelle équipe indépendante.'),('KT04','Bodylastics','Guide 136 pages','https://storage.googleapis.com/msgsndr/XvPdGEgSd8SLZjFiaiaQ/media/678d836801b601124c15cda0.pdf','squat poignées p.109, shoulder press p.119, reverse fly p.121 ; comparer sections barres et unilatérales','Texte original consulté. Captures demandées en échec. Sections avec barre et straps exclues comme procédures exactes du kit.'),('KT05','Peak Physio','Chest Press [Theraband]','https://www.peak-physio.com.au/exercise/chest-press-theraband/','Instructions : ancrage poitrine, pieds décalés, poussée et retour','Type bande/poignées pas complètement précisé, procédure de famille. Vidéo non visionnée.'),('KT06','Peak Physio','Shoulder Lateral Raise','https://www.peak-physio.com.au/exercises/strength-shoulder-lateral-raise-with-theraband/','Long arm variation et dumbbell','Bande, bras droit/paume bas et protocole clinique distincts des tubes/poignées à léger pli de Tempo. Doses non importées.'),('KT07','Burnlab','Overhead Triceps Extension','https://burnlab.co/blogs/blog/resistance-band-tricep-workout','Section 1 : tube sous un pied, poignées et coudes près oreilles','Verrouillage forcé et promesses de tête musculaire non retenus. Vidéo non visionnée.'),('KT08','Mirafit','5 Resistance Band Triceps Exercises','https://mirafit.co.uk/blog/5-resistance-band-triceps-exercises/','Sections reverse grip pushdown et overhead triceps','Prise inversée/unilatérale et long loop distinctes, soutien de famille ; aucune notice Decathlon.'),('KT09','Caliverse','Band Romanian Deadlift','https://www.caliverse.app/exercises/band-romanian-deadlift-805','Description : sous pieds, mains extérieures, bras longs, charnière, souffle et retour','Type bande plate versus tubes pas établi ; adaptation accessoire éditoriale. Vidéo non visionnée.'),('KT10','aerobis','Resistance Band Romanian Deadlift','https://aerobis.com/blogs/fitness/resistance-band-romanian-deadlift','Variation stand on band, prises extérieures','Boucle powerband différente ; images explicitement AI, pas démonstration humaine ni preuve tube exact.'),('KT11','MON Fitness','Resistance Band Exercise Library','https://monfitness.com/blogs/news/resistance-band-exercise-library','Banded squat, single-arm row, variantes de poussée et triceps','Guide commercial sans auteur identifié. Good morning autour du cou exclu, sans transfert de dose ni promesse.'),('KT12','GJELEMENTS','Guide exercices avec tubes','https://www.gjelements.com/wp-content/uploads/2020/12/Guide_d_exercice_GJELEMENTS.pdf','Titres tubes p.16-22','Texte/titres consultés, captures PDF échouées. Pas traité comme procédure complète ni validation des dessins.')]
sources=[dict(id=id,publisher=publisher,title=title,url=url,accessed='2026-10-12',consultedSection=section,limits=limits) for id,publisher,title,url,section,limits in urls]
refs={'EX17':['KT01','KT02','KT03','KT04','KT12'],'EX18':['KT01','KT02','KT06','KT04','KT12'],'EX23':['KT07','KT08','KT12','KT01'],'EX37':['KT02','KT04','KT11','KT01'],'EX38':['KT09','KT10','KT01'],'EX70':['KT01','KT02','KT03','KT05','KT12'],'EX71':['KT01','KT02','KT03','KT04','KT12'],'EX72':['KT02','KT03','KT04','KT11'],'EX73':['KT02','KT03','KT08','KT12'],'EX74':['KT04','KT01','KT12']}
variants=[e for e in json.loads((ROOT/'catalog/equipment-variants.json').read_text())['variants'] if e['id'] not in ['EX19','EX26']];new=[e for e in json.loads((ROOT/'catalog/kit-exercises.json').read_text())['exercises'] if int(e['id'][2:])<=74]
records=[]
for e in variants+new:
 records.append({'id':e['id'],'version':e['version'],'name':e['name'],'minimumLevelProposed':e['minimumLevel'],'documentaryStatus':'prototype_editorial_with_variant_limits_not_human_validated','source_ids':refs[e['id']],'bandMount':e['bandMount'],'positions':e['steps'],'muscles':e['muscles'],'muscleEvidence':'Rôles qualitatifs issus des fiches historiques et des descriptions de familles ; stabilisateurs et carte = synthèse anatomique à relire. Pas pourcentages EMG.','prerequisites':['Contrôler le mouvement sans tube avant de charger.','Montage conforme à la notice du matériel et retour sous tension maîtrisé.'],'errorsAndCorrections':e['errors'],'audioDraft':{'preparation':e['preparationCue'],'status':'system_voice_fallback_not_human_listened'},'media':{'status':'generated_illustrations_unreviewed','source':f'assets/sources/kit-expansion/{e["id"]}.png','continuousMotion':'not_produced_two_still_poses','technicalHumanReview':None},'evidenceByDomain':{'positions':'Noyau de famille recoupé ; prises, deux appuis, trajectoire et matériel exact distingués dans sources.limits.','muscles':'Reprise qualitative et inférences, pas mesures propres au kit.','advice':'Contrôle du retour/ancrage recoupé ; finesse de posture, amplitude et sortie = synthèse éditoriale.','media':'Prompts issus des consignes ; inspection assistant, aucune revue humaine ni trajectoire continue.','audio':'Texte issu de la synthèse, voix système, absence de clips F1/M2 et d’écoute humaine.'},'remainingUnresolved':['Notice et porte réelles pas homologuées par cette recherche.','Allongement admissible et résistance effective non déduits des kg nominaux.','Programmation, consignes et illustrations sans validation humaine.'],'localPrototypeIntegration':{'status':'integrated_illustrated_prototype','humanTechnicalReview':None}})
obj={'sources':sources,'exercises':[e for e in records if e['version']==1],'equipmentVariants':[e for e in records if e['version']==2],'method':'Documents ouverts et portée enregistrée. Nombre de liens différent du nombre de confirmations indépendantes. KT02/03 même éditeur. Certaines confirmations restent de famille et les modalités exactes restent partielles.','accessFailures':['Atemi PDF direct et miroir : lecteur web inaccessible ; téléchargement direct également échoué, donc pas utilisé comme confirmation consultée.','FitSimplify PDF : accès échoué, non utilisé comme confirmation.','Captures GJELEMENTS et Bodylastics indisponibles ; aucune revue des images de ces PDF déclarée.']}
(D/'kit-expansion.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
lines=['# Exercices adaptés au kit de résistance','','Cinq variantes d’accessoire et cinq nouveaux mouvements à ancrage. Consignes, prescription, illustrations et audio restent provisoires, sans revue humaine. Les 48 historiques, leurs versions et les 21 extensions restent conservés.','', 'Les nouvelles fiches sont distinctes quand posture ou ancrage changent. Curl haltères EX25 couvert par EX26 tubes existant ; rowing unilatéral EX20 rapproché du rowing bilatéral, sans prétendre conserver l’unilatéral ; développé serré et pompe résistée restent des gestes distincts du développé debout.','', '## Méthode et limites','',''+obj['method'],'']
for e in records:
 lines += [('## '+e['id'] if e['version']==1 else '### Variante '+e['id']+' v2')+' - '+e['name'],'',e['bandMount']+' ; niveau éditorial '+e['minimumLevelProposed']+'.',*['\n'+s['title']+' : '+s['description'] for s in e['positions']], '', 'Sources consultées : '+', '.join(e['source_ids'])+'.', 'Montage réel, entrée/sortie, dose, images et audio restent à revoir.','']
lines += ['## Sources consultées','']
for s in sources:lines += [f'- {s["id"]} [{s["publisher"]} - {s["title"]}]({s["url"]}) : {s["consultedSection"]}. {s["limits"]}']
lines += ['','## Accès échoués','']+obj['accessFailures']
(D/'kit-expansion.md').write_text('\n'.join(lines)+'\n')
